import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"更新日志 · XiHan Framework","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1794557980000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="更新日志-·-xihan-framework" tabindex="-1">更新日志 · XiHan Framework <a class="header-anchor" href="#更新日志-·-xihan-framework" aria-label="Permalink to “更新日志 · XiHan Framework”">​</a></h1><p>本页记录 XiHan Framework 各版本中使用者可感知的变更，每条标注 <strong>新增 / 修复 / 优化 / 调整 / 移除</strong> 类别；仓库自身的 CI、测试工程与构建脚本不列入。</p><h2 id="v5-0-0-rc-1-2026-11-13" tabindex="-1">v5.0.0-rc.1（2026-11-13） <a class="header-anchor" href="#v5-0-0-rc-1-2026-11-13" aria-label="Permalink to “v5.0.0-rc.1（2026-11-13）”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">候选版须知</p><ul><li>这是候选版，安装要带 <code>--prerelease</code>；正式版前只收修复与文档</li><li>这一版集中修复 5.0 安全审查的发现，多条要改配置或调用代码，升级前逐条看下面的迁移写法</li></ul></div><h3 id="版本与兼容" tabindex="-1">版本与兼容 <a class="header-anchor" href="#版本与兼容" aria-label="Permalink to “版本与兼容”">​</a></h3><ul><li><strong>新增</strong> 每个包带 SPDX 2.2 软件物料清单（包内 <code>_manifest/spdx_2.2/manifest.spdx.json</code>），列出包的组成与依赖</li></ul><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><ul><li><strong>修复</strong> 端点或路由组上的授权约定原先顶替了操作契约的权限：在 <code>MapXiHanOperations()</code> 上加 <code>RequireXiHanAuthentication()</code> 后，没有授予的已登录用户能调用全部操作；现在两者叠加判定，全部满足才放行。<code>FindAuthorizationRequirement</code> 改为 <code>GetAuthorizationRequirements</code>，返回全部已写入的要求</li><li><strong>修复</strong> 端点上的授权要求不再被静默跳过：挂在绕过管道的端点（OpenAPI、<code>.proto</code>、健康探针、自己标注绕过的）上时宿主启动失败（<code>SECURITY_VALIDATION_008</code>），原先从不判定；<code>UseXiHan()</code> 没调或排在 <code>UseRouting()</code> 之前时，带要求的端点拒绝执行；<code>MapXiHanGrpc()</code> 上的授权约定现在每次调用都判定</li><li><strong>修复</strong> HTTP 操作的请求体改在授权之后才读，原先进管道前就整读解析，匿名调用方也能让宿主为每个请求缓冲几十 MB；请求体上限 <code>XiHan:Protocols:Http:MaxRequestBodyBytes</code>（缺省 4 MiB，超过为 <code>PROTOCOLS_VALIDATION_011</code>），有请求体时 <code>Content-Type</code> 必须是 JSON（否则 <code>PROTOCOLS_VALIDATION_012</code>）：以 <code>text/plain</code> 或表单发 JSON 的客户端要改成 <code>application/json</code></li><li><strong>修复</strong> 进程外与 Wasm 插件读宿主配置节与绑定要运营方授予：原先插件在清单里点名哪个 <code>XiHan:*</code> 节、哪个绑定就拿到哪个，零权限的插件也能拿到 JWT 密钥、连接串与签名密钥；现在要在 <code>XiHan:Plugins:&lt;OutOfProcess|Wasm&gt;:Grants:&lt;清单 ID&gt;</code> 里授予 <code>config:&lt;配置节&gt;</code> 与 <code>binding:&lt;绑定名&gt;</code>，没有授予即拒绝加载（<code>PLUGINS_DENIED_001</code>）</li><li><strong>修复</strong> S3 命名实例必须给出 <code>AccessKey</code> 与 <code>SecretKey</code>：原先没给密钥就用宿主的 AWS 凭据链，能登记存储实例的租户管理员可以以宿主的身份读写任何桶；要用环境凭据由运营方打开 <code>XiHan:ObjectStorage:S3:NamedInstancesUseAmbientCredentials</code></li><li><strong>修复</strong> WebAuthn 认证核对凭据属于谁：原先只在存储与响应都带用户句柄时才比对，知道口令的攻击者能用自己账号下的通行密钥完成别人的登录。<code>WebAuthnStoredCredential.UserHandle</code> 改为必填，<code>VerifyAuthentication</code> 增加 <code>expectedUserHandle</code>（先认出用户时传他，免用户名传 <code>null</code>，此时响应必须带句柄），结果新增 <code>UserHandle</code></li><li><strong>修复</strong> OpenID Connect 缺省校验受众：原先没配 <code>Audience</code> 就不校验，共用身份提供方时发给别的应用的令牌也被接受。现在 <code>XiHan:Security:OpenIdConnect:Audience</code> 必填，没有即启动失败；签发者只为本 API 签发令牌时可以显式设 <code>ValidateAudience: false</code></li><li><strong>修复</strong> 工作流 <code>Http</code> 活动的正文读到 4 MiB 即停：原先先整体缓冲（上限约 2 GiB）再截断，能发布流程定义的租户用户把地址指向自己的服务器就能耗尽宿主内存。<code>TimeoutSeconds</code> 不超过 <code>XiHan:Workflow:MaxHttpTimeoutSeconds</code>（缺省 300），不是正的秒数时发布即校验失败，原先静默取缺省值</li><li><strong>修复</strong> 工作流的扇出与变量大小有了上限：原先并行 <code>ForEach</code> 的子实例数不受限，<code>s + s</code> 几十步就能拼出上 GB 的字符串，级联取消只处理最新的 1000 个子实例。现在 <code>ForEach</code> 最多 <code>XiHan:Workflow:MaxForEachItems</code> 项（缺省 1000），实例变量序列化后最多 <code>MaxVariablesBytes</code>（缺省 8 MiB），<code>+</code> 拼出的字符串最长 4194304 个字符，级联覆盖全部子实例</li><li><strong>修复</strong> 文件系统对象存储的配额改为边写边预留：原先只检查不预留，并发写入能合计超出 <code>MaxTotalBytes</code>，并发覆盖或删除同一个键会少记用量、之后一直能写到重启。覆盖写入现在需要新内容全长的余量</li><li><strong>修复</strong> 文件系统对象存储的分片暂存有了上限：原先暂存的分片不计入配额、上传数不限，过期的上传只在启动时清掉且之前照样能传分片。现在暂存计入 <code>MaxTotalBytes</code>，未完成的上传最多 <code>XiHan:ObjectStorage:FileSystem:MaxMultipartUploads</code>（缺省 1000），过期的上传拒绝再传分片与完成，运行期间也会清掉</li><li><strong>修复</strong> 进程外插件的 stdout / stderr 一行最多 16384 个字符：原先宿主按行整读，插件写一行不带换行的几十 MB 输出就让宿主整行装进内存。超过的部分丢弃并记一条告警，握手行超长即握手失败</li><li><strong>修复</strong> Wasm 插件沙箱补齐资源上限：睡在 WASI <code>poll_oneoff</code> 里的调用原先中断不了，宿主要等它睡完，现在最多睡到调用的截止时间即以 <code>KERNEL_TIMEOUT_001</code> 结束；<code>table.grow</code> 受 <code>XiHan:Plugins:Wasm:MaxTableElements</code>（缺省 100000）约束；<code>xihan.log</code> 一条最多 16384 字节；stdout / stderr 不再写进工作目录的文件，日志走 <code>xihan.log</code></li><li><strong>修复</strong> CloudEvents 入站端点的请求体与 batch 条数有了上限：原先整读请求体、batch 不限条数，派发模式下每个事件都走一次完整管道。现在请求体最多 <code>XiHan:Protocols:CloudEvents:MaxRequestBodyBytes</code>（缺省 1 MiB，超过为 <code>PROTOCOLS_VALIDATION_013</code>），batch 最多 <code>MaxBatchSize</code> 个事件（缺省 100，超过为 <code>PROTOCOLS_VALIDATION_014</code>）；<code>CloudEventsHttpBinding.ReadAsync</code> 多了 <code>options</code> 参数</li><li><strong>修复</strong> CloudEvents Webhook 发布方不再读接收方的响应体：原先先把整个响应缓冲进内存（上限约 2 GiB）再看状态码，接收方返回超大正文就能耗尽宿主内存；现在读到响应头即判定</li><li><strong>修复</strong> gRPC 解码嵌套消息最多 64 层：原先递归的消息描述能嵌套到第 1000 层，写 JSON 时以非预期异常失败，调用方得到 <code>Internal</code>；现在超过即 <code>InvalidArgument</code> + <code>PROTOCOLS_VALIDATION_005</code></li><li><strong>修复</strong> 知识库检索的条数与文档过滤有了上限：<code>Top</code> 最多 1000（<code>KnowledgeSearch.MaxTop</code>），<code>RetrievalFilter.DocumentIds</code> 最多 1000 个（<code>MaxDocumentIds</code>），超过在构造时抛出；原先条数不限、带元数据过滤时乘以超取倍数会溢出，向量存储把文档 ID 逐个左接成过滤表达式，现在拼成平衡的或树</li><li><strong>修复</strong> 审计不再把被 Tenant 阶段拒绝的租户记成事件的租户：原先安全上下文没有租户就回退到调用方自报的 Baggage，失败的调用落进不存在或已禁用的租户的审计；现在装配了多租户时只取安全上下文，自报的租户在结果的错误参数里。内核新增 <code>MarkTenantResolved()</code> / <code>IsTenantResolved()</code></li><li><strong>修复</strong> 配了 <code>XiHan:MultiTenancy:DefaultTenant</code> 或 <code>RequireTenant</code> 的宿主里，工作流轮询平台分区不再失败：原先平台分区的调用被补上缺省租户（存储发现分区不符即抛出）或因不带租户被拒绝。内核新增 <code>MarkPlatformCall()</code> / <code>IsPlatformCall()</code>，Tenant 阶段对声明的平台调用不补缺省租户、不要求带租户</li><li><strong>修复</strong> 租户分片的解析缓存过了 <code>XiHan:MultiTenancy:ShardCacheTimeToLiveSeconds</code>（缺省 30 秒）即重新读租户存储：原先从不过期，多实例部署里别的实例改了租户的连接串，本实例一直往旧库写。<code>TenantStoreShardResolver</code> 的构造多了 <code>TimeProvider</code></li><li><strong>修复</strong> 数据库授予的撤销在提交之后立即生效：原先只在写入时清缓存，撤销提交之前的判定会把已撤销的授予写回缓存，保留到存活时间结束（<code>CacheTimeToLiveSeconds</code> 为 0 时永久保留）；现在作用域结束时再失效一次，缓存丢弃失效之前开始的读取</li><li><strong>修复</strong> 数据库租户目录的停用与改连接串在提交之后立即生效：原先只在写入时清目录与分片缓存，提交之前的解析会把旧租户写回缓存，停用的租户在存活时间内仍被当作启用、仍指向旧库</li><li><strong>修复</strong> 插件回调与发布只能带宿主交给插件的租户：原先回调元数据里的 <code>xihan.tenant</code> 原样采用、Wasm 中间件也能改写它，插件能在任何启用的租户里调用宿主操作、发布消息。越界的回调与信封为 <code>PLUGINS_DENIED_002</code>，中间件改写租户被丢弃；原样转发收到的元数据的插件不受影响</li><li><strong>修复</strong> 租户 ID 只用小写（<code>^[a-z0-9][a-z0-9._-]{0,63}$</code>，整串匹配）：原先区分大小写，数据库缺省排序规则下 <code>ACME</code> 的调用能读写 <code>acme</code> 的行；<code>acme\\n</code> 这类结尾带换行的 ID 也曾被放过。含大写的 ID 为 <code>MULTITENANCY_VALIDATION_001</code>。升级前把租户目录、<code>TenantId</code> 列、授予与资源名里的租户 ID 改成小写，只有大小写不同的两个租户先拆开数据</li><li><strong>修复</strong> 没有租户的授予只对平台调用生效：原先它对每个租户生效，平台授给 <code>role:admin</code> 的权限落到每个租户里带同名角色、同一用户 ID 的人身上。要对每个租户生效的授予把范围写成 <code>*</code>（<code>PermissionGrant.AnyTenant</code>，数据库租户列存 <code>*</code>，内存配置写在 <code>XiHan:Security:InMemory:AnyTenantGrants</code>）；<code>GrantTenantFilter.Global</code> 改名 <code>Platform</code>，<code>PermissionGrantRecord.GlobalTenantId</code> 改名 <code>PlatformTenantId</code></li><li><strong>修复</strong> 多租户实体的唯一索引必须含 <code>TenantId</code>：原先不要求，撞上不含租户的唯一索引会告诉调用方别的租户已有这个键。不含又没写 <code>AcrossTenants = true</code> 的声明在启动时失败；主键仍全局唯一，多租户实体的标识应由服务端生成</li><li><strong>修复</strong> MCP 的 HTTP 端点校验 <code>Origin</code>、<code>Content-Type</code> 与请求体大小：原先任意网页都能用 <code>text/plain</code> 的简单请求调用本机 MCP 服务的匿名 tool，请求体也只受 Kestrel 的 30 MB 限制。带 <code>Origin</code> 的请求要在 <code>XiHan:Protocols:Mcp:AllowedOrigins</code> 里（否则 403），只收 <code>application/json</code>（否则 415），请求体最多 <code>MaxRequestBodyBytes</code>（缺省 4 MiB，否则 413）；浏览器里的 MCP 客户端要把它的源配进去</li><li><strong>修复</strong> CloudEvents 入站缺省只收 <code>XiHan:Protocols:CloudEvents:Topics</code> 映射过的事件类型：原先没有映射的类型以它本身为主题，只被允许投递某一种事件的发送方能投进任何有订阅的主题，包括插件订阅的主题。依赖类型直接当主题的应用把类型映射进 <code>Topics</code>，或在发送方可信时打开 <code>AcceptUnmappedTypes</code></li><li><strong>修复</strong> Kubernetes 租约客户端校验 API Server 证书的主机名与服务端认证用途：原先只核对证书链通到集群 CA，持有集群 CA 签发的任意证书就能冒充 API Server、拿到 ServiceAccount 令牌并伪造租约</li><li><strong>修复</strong> 宿主调用进程外插件时每次都带会话令牌，回调套接字放进私有目录：原先只有回调带令牌，本机其他用户或同一 Pod 的边车直接连插件端点就能冒充宿主，宿主的回调套接字也直接放在共享的临时目录下。插件必须校验 <code>xihan-plugin-session</code>，不符即 <code>Unauthenticated</code>；自己实现协议的插件要补上这道校验（.NET 写法见 <code>samples/EchoPlugin/SessionGuard.cs</code>）</li><li><strong>修复</strong> 极远的截止时间不再让调用以 500 结束：原先 <code>grpc-timeout</code> 的大数值溢出时间范围，超过约 49.7 天的截止时间让定时器构造抛出，匿名调用方能随意制造错误日志；现在前者截到最远的时刻，后者不起定时器</li><li><strong>修复</strong> Baggage 的值在建调用上下文时核对：原先原样进上下文，调用方能把换行写进关联 ID 伪造日志行，超长的值进日志、审计与信封。为空、超过 256 个字符或含控制字符的值丢弃（幂等键除外，照旧由 Idempotency 阶段拒绝）；HTTP 入站不合文法的 <code>xihan.locale</code> 当作没给，<code>Accept-Language</code> 照常协商</li><li><strong>修复</strong> 幂等的作用域键里主体带长度前缀：原先主体 ID 直接拼接，主体 <code>a:b</code> 配键 <code>c</code> 与主体 <code>a</code> 配键 <code>b:c</code> 共用一条记录，能回放别人的结果；升级前写下的幂等记录不再命中（保留期内的重试会再执行一次）。MCP 的 HTTP 传输把幂等键交给 <code>tools/call</code>：原先外层请求先写下「处理中」，同一个键的工具调用一次也执行不了</li><li><strong>修复</strong> 出站地址策略在开了私网时同样拒绝 GCP（<code>fd20:ce::254</code>）与 Oracle（<code>fd00:c1::a9fe:a9fe</code>）的 IPv6 元数据地址：原先只拒绝 AWS 的，另两个能连到并取得实例凭据</li><li><strong>修复</strong> 插件工作目录缺省按用户分开（<code>&lt;临时目录&gt;/xihan-plugins-&lt;用户名&gt;</code>、<code>xihan-plugins-wasm-&lt;用户名&gt;</code>），Unix 上必须是本用户私有的真实目录：原先是临时目录下名字固定的目录，别的用户能抢先建成指向别处的链接。插件留在旧缺省目录里的数据不会自动搬过去，要保留就把 <code>WorkDirectory</code> 配回旧位置</li><li><strong>修复</strong> 进程外插件不再按 <code>GO</code> 前缀继承宿主的环境变量：原先 <code>GOOGLE_APPLICATION_CREDENTIALS</code> 等 Google 云凭据随之交给了插件；现在 Go 只继承 <code>GOMAXPROCS</code>、<code>GOGC</code>、<code>GOMEMLIMIT</code>、<code>GODEBUG</code>、<code>GOTRACEBACK</code></li><li><strong>调整</strong> 健康探针只给 <code>status</code> 与 <code>state</code>：原先匿名访问者能读到全部特性、健康条目与它们的描述和数据。详情改由新的 <code>MapXiHanHealthDetails()</code>（<code>/health/details</code>）给出，它经内核管道、能加访问要求。MCP 的 <code>serverInfo.version</code> 缺省改为应用的版本，不再是框架版本</li><li><strong>修复</strong> 知识库的默认集合按租户分开：原先请求不指明集合时所有租户共用 <code>knowledge</code>，一个租户摄入的内容别的租户检索得到。带租户的调用现在用 <code>knowledge.&lt;租户 ID&gt;</code>，要共享就显式指明集合；<code>IKnowledgeIngestor</code> 与 <code>IKnowledgeRetriever</code> 改为作用域服务，在根容器里直接取用的代码要先建作用域；已经摄入在共享集合里的内容要重新按租户摄入</li><li><strong>修复</strong> 发件箱投递循环覆盖租户分片库：原先只轮询默认库，EF Core 在带分片的调用里写进租户库的消息发不出去。每轮先投递默认库，再逐个投递分片库；新增 <code>XiHan:Messaging:Outbox:IncludeShards</code>（默认 <code>true</code>）与 <code>ShardRefreshIntervalSeconds</code>（默认 60）。EF Core 下带分片的调用要发消息，分片库要建发件箱表</li><li><strong>修复</strong> 文件系统对象存储不再把键里含 <code>.xihan-tmp-</code> 的对象当作临时文件：原先这样的对象列举不到、重启时被删除，根路径含这段文字时整个存储重启后清空。临时文件片段改为 <code>~xihan-tmp-</code>，只按文件名判定</li><li><strong>修复</strong> 文件系统对象存储按首个点之前判定 Windows 设备名并补上 <code>com0</code>、<code>lpt0</code>，<code>RootPath</code> 去掉结尾的分隔符：原先 <code>con.tar.gz</code> 这样的键段在 Windows 上写不进去，<code>RootPath</code> 以分隔符结尾时每个操作都抛异常。Linux 与 macOS 上已有的这类键（如 <code>nul.tar.gz</code>、<code>com0</code>）换了文件名，升级后要重新写入，或把文件与元数据文件的首字符改成 <code>%XX</code></li><li><strong>调整</strong> 对象的内容类型按媒体类型文法（最长 255 个字符），自定义元数据值不含控制字符、名与值合计不超过 2048 个 UTF-8 字节：原先换行能进 S3 的请求头，元数据不限大小。不合法时 <code>BlobPutOptions</code> 抛出 <code>ArgumentException</code>；把客户端给的内容类型交给它之前先用 <code>BlobPutOptions.IsValidContentType</code> 判断。宿主直传端点对不合法的请求内容类型返回 <code>OBJECTSTORAGE_VALIDATION_006</code>（HTTP 400）</li><li><strong>修复</strong> 雪花机器位租约改为原子续约：原先续约是释放再获取，释放的那一刻别的实例能拿到同一机器位，两边会发出相同的 ID。<code>ICacheStore</code> 新增 <code>TryRefreshAsync</code>（比较后重设到期），<code>LockHandle</code> 新增 <code>TryExtendAsync</code>；自己实现 <code>ICacheStore</code> 或派生 <code>LockHandle</code> 的要补上这两个成员。远程缓存插件的操作集新增 <code>cache-entries.try-refresh</code>，插件要实现它</li><li><strong>修复</strong> WebAuthn 认证在验签之后才判定凭据属于谁，RSA 公钥的模长不超过 4096 位：原先没有私钥的人能从失败原因分辨凭据属于哪个用户，几万位的模数让每次验签都很慢。文档不再建议拿 <code>Aaguid</code> 做型号白名单（<code>none</code> 证明下它是认证器自报的）</li><li><strong>调整</strong> 没有装配授权能力时，契约声明了权限或策略的操作、挂了 <code>RequireXiHan*</code> 的端点让启动失败（<code>KERNEL_VALIDATION_006</code>）：原先要求静默失效，操作与端点等于敞开。之后登记的这类插件操作登记失败，启动之后才写入的 <code>RequireAuthorization</code> 抛出 <code>InvalidOperationException</code>。迁移：装配 <code>Security.InMemory</code> 或 <code>Security.Database</code>，或去掉这些要求</li><li><strong>调整</strong> 已认证主体带多个值不同的租户声明时拒绝调用（<code>MULTITENANCY_VALIDATION_004</code>）：原先取第一个，签发方给出矛盾的身份时调用落进其中任意一个租户</li><li><strong>调整</strong> 预签名限定的内容类型须合内容类型文法，保存的文件名不含控制字符、最长 255 个字符：原先只要求不空白，带换行的值能在宿主签名的规范串里把一项挪成另一项</li><li><strong>调整</strong> Nacos 的令牌改走 <code>Authorization: Bearer</code> 请求头、不进查询串，失败原因不再带响应正文；配置了用户名密码时非本机的 <code>http</code> 地址默认拒绝，链路另有保护时设 <code>XiHan:Configuration:Nacos:AllowInsecureHttp</code> 为 <code>true</code></li><li><strong>修复</strong> <code>xihan migrate</code> 与 <code>xihan setup</code> 遍历时不再跟随符号链接与目录联接：原先链接指向 <code>--path</code> 之外时迁移会改写别处的文件，链接成环时遍历到路径过长才失败</li><li><strong>调整</strong> <code>xihan pack</code> 发现进 ConfigMap 的配置文件里有带值的凭据键时失败（<code>CLI_VALIDATION_007</code>），只列键的路径、不带值：原先配置文件原样进不加密的 ConfigMap。凭据改放绑定的 Secret 或环境变量，或在这些文件里留空</li><li><strong>修复</strong> 客户端建在租户分片上时，工作单元的租户必须是这个分片的租户，不一致即抛出 <code>PERSISTENCE_VALIDATION_010</code>：原先不核对，管道外以别的租户开工作单元会把那个租户的行写进这个分片库</li><li><strong>修复</strong> EF Core 的多租户实体加全局查询过滤器 <code>xihan:tenant</code>：原先只有仓储按租户过滤，直接用工作单元的 <code>Context</code> 或注入的 DbContext 查询能读到别的租户的行。有意跨租户时用 <code>IgnoreQueryFilters([ModelBuilderExtensions.TenantQueryFilter])</code>；多租户实体上已有匿名过滤器的要给它起名</li><li><strong>调整</strong> 删除租户留墓碑：删除的 ID 读不到，也不能再新建（<code>MULTITENANCY_CONFLICT_001</code>）。原先删了再建同一个 ID，新租户会接手旧租户留下的数据。<code>TenantRecord</code> 改为软删除，已有的表要加 <code>IsDeleted</code>、<code>DeletedAt</code> 两列；内存实现的墓碑计入 <code>MaxTenants</code></li></ul><h3 id="宿主、协议与插件" tabindex="-1">宿主、协议与插件 <a class="header-anchor" href="#宿主、协议与插件" aria-label="Permalink to “宿主、协议与插件”">​</a></h3><ul><li><strong>新增</strong> 插件协议的 <code>HandleEventRequest</code> 带这次投递的订阅方式 <code>mode</code>，宿主总是填写，插件只交给以这种方式订阅的处理器。原先同一主题的不同类型各用一种方式时，插件分不出投递来自哪种订阅。自己从 <code>plugin.proto</code> 生成桩的插件要重新生成，并在 <code>HandleEvent</code> 里按 <code>mode</code> 分派</li><li><strong>修复</strong> 进程外插件在握手期间被取消时先终止并回收进程：原先取消越过释放，已启动的插件进程无人回收；插件进程先退出时，终止与握手的等待随即结束，不再空等到时限</li></ul><h2 id="v5-0-0-preview-3-2026-11-12" tabindex="-1">v5.0.0-preview.3（2026-11-12） <a class="header-anchor" href="#v5-0-0-preview-3-2026-11-12" aria-label="Permalink to “v5.0.0-preview.3（2026-11-12）”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，安装要带 <code>--prerelease</code>；公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整</li><li>这一版集中调整了正式版前的公共 API，多数条目要改调用代码，升级前逐条看下面的迁移写法</li></ul></div><h3 id="版本与兼容-1" tabindex="-1">版本与兼容 <a class="header-anchor" href="#版本与兼容-1" aria-label="Permalink to “版本与兼容”">​</a></h3><ul><li><strong>调整</strong> 稳定性级别的承诺：<code>Stable</code> 大版本内不破坏；<code>Preview</code> 与 <code>Experimental</code> 可能在小版本变更，补丁版本不变，每次变更在本页写明迁移方式；要求升级不改代码就只用 <code>Stable</code> 的 API（见 <a href="/getting-started/concepts#稳定性分级">稳定性分级</a>）</li><li><strong>调整</strong> 5.0 的级别定准：配置、对象存储、审计的抽象，七个默认实现与 Redis 缓存、RabbitMQ、SqlSugar、OpenTelemetry，调度的应用面（<code>IJob</code>、<code>IJobScheduler</code>、作业定义、计划与日历）、工作流的定义模型与 <code>WebApplicationBuilder.AddXiHan</code> 升为 <code>Stable</code>；三个 Profile、发件箱与全部一致性套件降为 <code>Preview</code>；<code>HttpActivity</code>、<code>WorkflowHttpClient</code> 与 SqlSugar 的读写分离、差异日志降为 <code>Experimental</code>。各包页的「稳定性」一行写明例外</li></ul><h3 id="原语与内核" tabindex="-1">原语与内核 <a class="header-anchor" href="#原语与内核" aria-label="Permalink to “原语与内核”">​</a></h3><ul><li><strong>新增</strong> 宿主启动时向标准输出打印启动 Banner（版式同 4.x），<code>XiHan:Kernel:Banner:Enabled=false</code> 关闭，以 JSON 行收集 stdout 的部署应关掉；命令行宿主缺省不打印（见<a href="/startup/bootstrap#启动-banner">装配入口</a>）</li><li><strong>移除</strong> <code>CapabilityAttribute</code>：没有使用者，运行期也不读，随清单生成器一起提供；<code>CapabilityResolver</code> 与 <code>NullAuditSink</code> 不再公开，能力求解经 <code>AddXiHan</code> 装配，结果从 <code>ResolvedGraph</code> 读取</li><li><strong>调整</strong> <code>OperationContract</code> 构造只收 ID，其余字段改为初始化器：手写的 <code>new OperationContract(id, stability, expose, policy, permission, readOnly)</code> 改成 <code>new OperationContract(id) { Stability = …, Expose = …, Policy = …, Permission = …, IsReadOnly = … }</code>；用生成器的项目重新编译即可，生成的 <code>GeneratedOperations</code> 变为 internal</li><li><strong>调整</strong> <code>Expose.All</code> 冻结为 5.0 的五个协议：以后新增的协议不并入 <code>All</code>，要在新协议上发布须显式开启；现有行为不变</li><li><strong>调整</strong> 清单记录的可选字段改为初始化器：<code>new Binding(name, type) { Required = false }</code>、<code>new CapabilityRequirement(id, version) { Optional = true }</code>、<code>new ConfigContribution(section) { Schema = … }</code>、<code>new PipelineContribution(middleware, stage) { Before = …, After = … }</code>（<code>PipelineContribution</code> 不再是位置记录）</li><li><strong>调整</strong> <code>Error.Unexpected</code> 的参数顺序改为 <code>(code, messageKey, details, inner)</code>，与构造函数一致；只传内部错误的写成 <code>Error.Unexpected(code, messageKey, null, inner)</code></li><li><strong>调整</strong> <code>Stable</code> 的公开方法与构造不再带可选参数，改为重载（<code>Error</code> 的构造与工厂、<code>PipelineBuilder.UseAt</code> / <code>UseInstance</code> / <code>UseNamedInstance</code>、<code>FeatureContext.AddMiddleware</code>、<code>ProblemResponse.FromError</code>、<code>BlobUrlRequest.ForDownload</code> / <code>ForUpload</code> 等）：用命名实参跳过前面参数的调用补上被跳过的参数，如 <code>UseAt&lt;T&gt;(stage, Placement.End, owner)</code>、<code>ForDownload(null, fileName)</code></li><li><strong>调整</strong> <code>SchemaViolation</code> 的消息键与参数改为初始化器：<code>new SchemaViolation(path, reason, key, args)</code> 改成 <code>new SchemaViolation(path, reason) { MessageKey = key, Arguments = args }</code></li><li><strong>新增</strong> 分析器规则 XH0006～XH0008：<code>Stable</code> 的签名不得引用 <code>Preview</code> / <code>Experimental</code> 类型，成员级别不得高于所在类型，<code>Stable</code> 不得声明可选参数</li><li><strong>修复</strong> <code>CapabilityDeclaration.TryParse</code> 与 <code>CapabilityRequirement.TryParse</code> 的输出标注为可空（<code>[NotNullWhen(true)]</code>），失败时为 <code>null</code></li><li><strong>修复</strong> <code>InvocationContext.Baggage</code> 构造时复制成只读副本，调用方之后改原字典不再影响上下文；<code>Items</code> 在派生上下文之间共享，并行写入时不再损坏</li><li><strong>调整</strong> 匿名主体的 <code>Principal.Id</code> 由空字符串改为 <code>null</code>，<code>new Principal(id, scheme)</code> 只创建已认证主体（两者都不得为空），匿名用 <code>Principal.Anonymous</code>；判断 <code>IsAuthenticated</code> 之后可直接用 <code>Id</code>。<code>ResourceName.Tenant</code> 的全局资源由空字符串改为 <code>null</code>，构造时校验每一段</li><li><strong>调整</strong> 内核的数据类型不再是位置记录：<code>AuditEvent</code>、<code>HealthSnapshot</code>、<code>OperationResponse</code>、<code>FeatureStatus</code> 按属性名写初始化器（<code>new AuditEvent { Timestamp = …, Action = …, Outcome = …, TraceId = … }</code>）；<code>AuthorizationRequest</code>、<code>ContributorStatus</code>、<code>PluginSource</code> 只保留两参构造，第三个实参改成初始化器（<code>new ContributorStatus(name, state) { Error = … }</code>）；这些类型都不再能解构</li><li><strong>调整</strong> 返回 <code>Maybe</code> 的查找统一叫 <code>Find…</code>：<code>GetOutcome</code> / <code>GetOrigin</code> / <code>GetOperation…</code> / <code>GetCredential</code> / <code>GetAuthorizationRequirement</code> / <code>GetTenantShard</code> / <code>GetAuditAction</code> / <code>GetAuditResource</code> / <code>GetDelivery</code> / <code>GetRun</code> / <code>GetXiHanContext</code> 与按键读条目的 <code>Get&lt;T&gt;</code> 改成对应的 <code>Find…</code>，<code>TryGetBinding</code> 改成 <code>FindBinding</code>，插件宿主的 <code>Describe</code> 改成返回 <code>Maybe</code> 的 <code>FindStatus</code>；<code>GetAuditDetails</code> 改成 <code>FindAuditDetails</code> 并返回只读副本；<code>WorkflowVariables</code> 删掉 <code>Get</code> / <code>Get&lt;T&gt;</code>，改用索引器与 <code>TryGet&lt;T&gt;</code></li><li><strong>调整</strong> <code>App.CreateContext</code> 的可选参数收进新的 <code>InvocationContextOptions</code>：<code>App.CreateContext(sp, ct, deadline: d, baggage: b)</code> 改成 <code>App.CreateContext(sp, new InvocationContextOptions { Deadline = d, Baggage = b }, ct)</code>，只传服务与令牌的不用改；<code>DomainEventBuffer</code> 改为无参与 <code>(int capacity)</code> 两个构造，<code>Items</code> 交出只读视图</li></ul><h3 id="子系统" tabindex="-1">子系统 <a class="header-anchor" href="#子系统" aria-label="Permalink to “子系统”">​</a></h3><ul><li><strong>新增</strong> <code>Security.WebAuthn</code>：通行密钥的依赖方实现，提供 <code>security.webauthn@1</code>。<code>WebAuthnCeremonies</code> 生成与 WebAuthn Level 3 JSON 同形的注册与认证选项，按 RFC-0008 的顺序核对响应（ES256 / PS256 / RS256，证明一律按 <code>none</code>）；无状态，挑战与凭据由应用保存。配置节 <code>XiHan:Security:WebAuthn</code>，<code>RelyingPartyId</code> 与 <code>Origins</code> 必填。新错误码 <code>SECURITY_VALIDATION_006</code> / <code>007</code>、<code>SECURITY_DENIED_005</code> / <code>006</code>（签名计数没有增加）（ADR-0170）</li><li><strong>新增</strong> <code>Testing</code> 的 <code>WebAuthnTestAuthenticator</code> 与 <code>WebAuthnTestCeremony</code>：测试里生成合法或篡改过的通行密钥响应；<code>Testing</code> 随之依赖 <code>Security.WebAuthn</code> 与 <code>System.Formats.Cbor</code></li><li><strong>新增</strong> <code>Messaging.Redis</code>：用 Redis Streams 提供 <code>messaging.queue@1</code>，只有 Redis 的部署也能跨进程收发消息；需显式 <code>UseFeature&lt;RedisMessagingFeature&gt;()</code>，配置节 <code>XiHan:Messaging:Redis</code>，可选绑定 <code>queue</code>（类型 <code>cache:distributed</code>），需要 Redis 6.2+，不提供 <code>messaging.stream@1</code>（见 <a href="/packages/messaging-redis">Messaging.Redis</a>）</li><li><strong>修复</strong> 工作流启动请求不再公开 <code>InstanceId</code>、<code>ParentInstanceId</code>、<code>ParentNodeInstanceId</code> 与 <code>Depth</code>：调用方原先能借它们伪造子流程的父链接、绕过嵌套深度上限；这几个字段只由引擎为子流程设置，给它们赋值的代码删掉即可，要幂等启动用 <code>CorrelationId</code> 与 <code>ReusePolicy</code></li><li><strong>修复</strong> 活动、结果处理器与指派规则拿到的 <code>Instance</code>、<code>NodeInstance</code> 改为只读视图 <code>WorkflowInstanceView</code> / <code>WorkflowNodeInstanceView</code>：原先交出的是引擎随后写回的对象，扩展代码改了状态或租户会被持久化；只读的代码不用改，要读变量与私有状态改用上下文的 <code>Variables</code> 与 <code>State</code></li><li><strong>修复</strong> 用户任务与外部任务的书签不能再经 <code>IWorkflowEngine.ResumeAsync</code> 直接消费：原先绕过指派人与持锁工作者的校验、也不发完成事件，现在返回 <code>WORKFLOW_CONFLICT_003</code>；办理任务改用 <code>IWorkflowTaskService.CompleteAsync</code>，外部任务改用 <code>IWorkflowExternalTaskService.CompleteAsync</code> / <code>FailAsync</code></li><li><strong>调整</strong> 工作流的引擎、定义目录、任务与外部任务服务的实现类型，<code>ActivityRegistry.Add</code> 与 <code>GetActivityRegistry</code>，实例的 <code>JoinStates</code> 与 <code>WorkflowJoinState</code>，以及 <code>Workflow.Database</code> 的实例锁与轮询类型不再公开：经 <code>IWorkflowEngine</code> 等接口与 <code>AddActivity&lt;TActivity&gt;</code> 使用；<code>WorkflowEngine.LastErrorVariable</code> 等常量移到 <code>WorkflowReservedNames</code>，成员名不变，只改类名</li><li><strong>调整</strong> 调度与配置的实现细节不再公开：<code>JobPlanner</code>、<code>InMemorySchedulingHealthContributor</code>、<code>NacosDocumentParser</code>，以及 <code>KubernetesSchedulingOptions</code> 的 <code>ResolveNamespace</code> / <code>ResolveHolder</code> / <code>ResolveApiServer</code> / <code>LeaseNameFor</code>；它们只在各自的包里用</li><li><strong>调整</strong> <code>JobRegistry</code>、<code>JobTypeRegistry</code>、<code>JobCalendars</code> 的 <code>Add</code> 不再公开：装配之后只读，登记作业、作业类型与日历用 <code>AddJob</code>、<code>AddJobType</code>、<code>AddJobCalendar</code></li><li><strong>调整</strong> 持久化、本地化、缓存与消息的实现类型不再公开：三个 Provider 的仓储实现、<code>InMemoryUnitOfWork</code>、<code>InMemoryTable</code> 与 <code>InMemoryStore.Table</code>、<code>LeasedWorkerIdSource</code>、<code>RepositoryRegistrations.Items</code>、<code>MessageCatalog.ParseLocaleFile</code>、<code>CacheStoreDistributedCache.Translate</code>、领域事件的登记表、映射与派发器、三个消息代理的连接与探测成员、<code>OpenIdConnectMetadataCache.FailureRetryDelay</code>；照常经 <code>IRepository</code>、<code>IUnitOfWork</code>、<code>AddDomainEvent&lt;TEvent&gt;</code> 等入口使用</li><li><strong>调整</strong> <code>IPermissionGrantStore</code> 改为批量读取 <code>GetManyAsync(subjects, tenantId)</code>，权限判定把用户与全部角色一次读出；实现授予存储的 Provider 把 <code>GetGrantsAsync</code> 换成 <code>GetManyAsync</code>，单主体的 <code>GetGrantsAsync</code> 仍可调用（扩展方法）</li><li><strong>新增</strong> 授予管理的可选接口 <code>IPermissionGrantAdministration</code>，内存与数据库实现都提供：<code>GrantAsync</code> / <code>RevokeAsync</code> 与入参同序的逐项结果（撤销不存在是 <code>SECURITY_NOTFOUND_002</code>），<code>ListAsync(PermissionGrantQuery)</code> 按主体与租户（<code>GrantTenantFilter.Any</code> / <code>Global</code> / <code>Of(tenantId)</code>）过滤、分页并计数，越界为新错误码 <code>SECURITY_VALIDATION_005</code>；<code>InMemoryPermissionGrantStore.Grant</code> / <code>Revoke</code> 不再公开，<code>PermissionGrantRecordStore.ListAsync(subject, tenantId, skip, take)</code> 删除，改用接口</li><li><strong>调整</strong> 审计查询新增 <code>AuditQuery.Resource</code>（<code>xrn:</code> 文本精确匹配），数据库实现加 <code>(Resource, Sequence)</code> 索引；审计细节统一为 JSON 值：<code>AddAuditDetail(key, JsonNode?)</code>（简单值写法不变），<code>AuditEvent.Details</code> 改为 <code>IReadOnlyDictionary&lt;string, JsonElement&gt;?</code>，内存与数据库读回同一类型，读细节的代码改用 <code>GetDecimal()</code> / <code>GetString()</code> 等</li><li><strong>调整</strong> <code>AuditQuery</code> 的 <code>PrincipalId</code> / <code>TenantId</code> 改为显式过滤 <code>Principal</code>（<code>AuditPrincipalFilter</code>）与 <code>Tenant</code>（<code>AuditTenantFilter</code>），能只查匿名调用或平台级事件：<code>new AuditQuery { TenantId = id }</code> 改成 <code>new AuditQuery { Tenant = AuditTenantFilter.Of(id) }</code>，主体同理</li><li><strong>调整</strong> <code>ITenantStore.FindAsync</code> 返回 <code>Result&lt;Maybe&lt;TenantInfo&gt;&gt;</code>，存储不可达是 <code>MULTITENANCY_UNAVAILABLE_003</code>（Tenant 阶段以 503 结束，不再当作 500 抛出）；<code>ListAsync(TenantQuery)</code> 改为分页，逐页读到 <code>ContinuationToken</code> 为空；自己实现租户存储的 Provider 改这两个方法</li><li><strong>新增</strong> 租户管理的可选接口 <code>ITenantAdministration</code>（<code>UpsertAsync</code> / <code>RemoveAsync</code> 与入参同序的逐项结果，写后失效目录与分片缓存），内存与数据库实现都提供；<code>InMemoryTenantStore.Set</code> / <code>Remove</code> 不再公开（内存实现写入后也会失效分片缓存了），<code>TenantRecordStore.ListAsync(skip, take)</code> 删除，改用 <code>ITenantStore.ListAsync</code></li><li><strong>调整</strong> 缓存失效统一为 <code>Invalidate(ids)</code> 加 <code>InvalidateAll()</code>，不再以 <code>null</code> 表示全部：<code>ITenantShardResolver</code>、<code>IAIProviderCatalog</code>、<code>DatabaseTenantStore</code>、<code>DatabasePermissionGrantStore</code>；<code>Invalidate(&quot;acme&quot;)</code> 改为 <code>Invalidate([&quot;acme&quot;])</code>，无参调用改为 <code>InvalidateAll()</code></li><li><strong>调整</strong> <code>ITenantResolver.ResolveAsync</code> 返回 <code>Result&lt;Maybe&lt;string&gt;&gt;</code>，自定义解析器可以返回失败拒绝调用（以该错误结束，后面的解析器与默认租户不再顶替）；实现解析器的应用把返回值包进 <code>Result.Success(…)</code></li><li><strong>调整</strong> <code>IMessageLocalizer</code> 只留 <code>Options</code>、<code>Find</code>、<code>Resolve(key, locale, arguments)</code>，其余 <code>Localize</code> / <code>Resolve(error, …)</code> 改为 <code>MessageLocalizerExtensions</code> 的扩展方法：调用方不用改，自己实现本地化器的 Provider 删掉这 5 个成员</li><li><strong>调整</strong> <code>IAuditSink.WriteAsync</code> 的契约写明不抛出：接收不下或落地失败时由实现自己丢弃、计数并告警，返回只表示已接收；自己实现接收器的 Provider 需通过一致性套件新增的用例</li><li><strong>移除</strong> <code>XiHan:MultiTenancy:Database:MaxListedTenants</code>：租户列表分页之后不再截断，删掉这个配置键</li><li><strong>调整</strong> <code>MessageDelivery</code> 改为初始化器（<code>new MessageDelivery { Topic = …, Envelope = …, Attempt = …, Mode = … }</code>），<code>MessageSubscription</code> 只保留 <code>(topic, mode)</code> 构造；<code>IdempotencyRecord</code> 不再公开，记录格式与回放不变</li><li><strong>调整</strong> 调度器的状态与历史改为只读视图：<code>RunsAsync</code> 返回 <code>JobRunView</code>（失败结果在 <code>Outcome</code>），<code>JobStatus.Job</code> 是 <code>JobView</code>；<code>StatusesAsync()</code> 改为分页的 <code>ListStatusesAsync(new JobStatusQuery())</code>，按名批量用 <code>StatusesAsync(names)</code>，<code>StatusAsync(name)</code> 不变；<code>new JobTriggerRequest(name, data)</code> 改为 <code>new JobTriggerRequest(name) { Data = data }</code>，<code>JobRun</code>、<code>JobOutcome</code>、<code>JobTriggerStatus</code>、<code>JobStatus</code> 按属性名初始化</li><li><strong>调整</strong> 调度器的批量方法中途取消不再抛出：已开始的项照常给出结果，未开始的项以 <code>KERNEL_CANCELLED_001</code> 结束；开始前已取消时仍抛出</li><li><strong>移除</strong> <code>IWorkflowTaskService.PendingAsync</code> 与 <code>PendingByInstanceAsync</code>：待办一律分页读取，改为 <code>QueryAsync(new UserTaskQuery { AssigneeId = … })</code> 或 <code>{ InstanceId = … }</code></li><li><strong>调整</strong> 工作流的批量方法传空集合时直接返回空结果，不再开一次调用</li><li><strong>调整</strong> <code>IBlobStoreProvider.CreateAsync</code> 与 <code>IDataSourceProvider.CreateAsync</code> 以结果报告失败（<code>Result&lt;IBlobStore&gt;</code> / <code>Result&lt;IDataSource&gt;</code>），不再抛出：自己写存储或数据源 Provider 的改返回类型，拒绝定义用 <code>BlobStoreFailures</code> / <code>DataSourceFailures</code>；经注册表使用的应用不受影响</li><li><strong>调整</strong> 工作流的任务与控制请求改为初始化器：<code>new UserTaskCompletion(taskId, actorId) { Outcome = …, Comment = … }</code>，外部任务请求保留 <code>(taskId, workerId)</code>，<code>new WorkflowJump(instanceId, targetNodeId) { Reason = … }</code>、<code>new WorkflowVariableUpdate(instanceId) { Variables = …, Remove = … }</code>；<code>UserTaskPage</code>、<code>BlobMetadata</code>、<code>BlobPage</code>、<code>EntityColumnMapping</code>、<code>SqlSugarDiffLogData</code> 按属性名初始化，这些类型都不再能解构</li><li><strong>调整</strong> 待办查询的 <code>UserTaskQuery.Descending</code> 改为排序项列表 <code>Sorts</code>（<code>UserTaskSort</code> / <code>UserTaskSortField</code>，与定义、实例查询同一写法）：<code>Descending = true</code> 改成 <code>Sorts = [new(UserTaskSortField.CreatedAt, Descending: true)]</code>；状态序号 <code>WorkflowStatusOrder.Of</code> 移到 <code>Workflow.Abstractions</code> 公开一份，存储实现共用</li><li><strong>调整</strong> 字符串承载的标识（<code>CacheKey</code>、<code>BlobKey</code>、<code>ContainerName</code>、<code>JobName</code>、<code>WorkflowName</code>、<code>ActivityType</code>、<code>SecretName</code>）不再从 <code>string</code> 隐式转换：传字符串的地方写 <code>new JobName(&quot;cleanup&quot;)</code> 或 <code>(JobName)&quot;cleanup&quot;</code>；这些类型与 <code>GrantSubject</code>、<code>TriggerKey</code> 的 <code>default</code> 值读文本抛 <code>InvalidOperationException</code>，<code>PermissionGrant</code> 与 <code>TriggerKey</code> 拒收 <code>default</code> 成员</li><li><strong>调整</strong> 分页统一成两种形状：偏移分页 <code>Skip</code> / <code>Take</code>（<code>MaxTake</code>，页为 <code>Items</code> 与 <code>long Total</code>），续页分页 <code>PageSize</code> / <code>ContinuationToken</code>（页为 <code>Items</code> 与 <code>ContinuationToken</code>）；调度运行历史与工作流的定义、实例、待办查询的 <code>Limit</code> / <code>MaxLimit</code> 改为 <code>Take</code> / <code>MaxTake</code>，<code>CacheKeyQuery</code> 的 <code>Limit</code> / <code>Continuation</code> 改为 <code>PageSize</code> / <code>ContinuationToken</code>，<code>CacheKeyPage.Keys</code> 与 <code>AuditPage.Events</code> 改为 <code>Items</code>，分页错误的参数 <code>limit</code> 改为 <code>take</code> / <code>pageSize</code></li><li><strong>调整</strong> 批量的逐项结果统一为与入参同序的 <code>Result</code> 列表：<code>BlobPutResult</code>、<code>BlobDeleteResult</code>、<code>JobTriggerResult</code>、<code>TenantRecordResult</code>、<code>MessageTranslationResult</code>、<code>PermissionGrantResult</code> 删除，读 <code>result.Outcome</code> 的地方直接用列表元素，要键时按下标取入参；实现 <code>IBlobStore</code> 的 Provider 改 <code>PutAsync</code> / <code>DeleteAsync</code> 的返回类型</li><li><strong>修复</strong> 分片上传句柄 <code>BlobMultipartUpload</code> 的覆盖标志改为必填的初始化成员：原先重建句柄时漏传参数会把「不覆盖」静默变成「覆盖」（S3 完成时按句柄决定条件写入），写成 <code>new BlobMultipartUpload(container, key, uploadId) { Overwrite = … }</code>；<code>FileSystemBlobStore</code> 只经 <code>CreateAsync</code> 创建（扫描已用量后才交出），<code>BlobStoreConformance.CreateStore()</code> 改为 <code>CreateStoreAsync()</code></li><li><strong>修复</strong> 文件系统对象存储在 Linux 与 macOS 上并发的不覆盖写入（含分片上传的完成）偶发两个都成功、后写的覆盖先写的：改为先独占创建占位文件再替换内容；Windows 上仍用不替换的改名</li><li><strong>调整</strong> <code>SnowflakeId</code> 不再能逐项构造，只经 <code>SnowflakeId.Parse(value, epoch)</code> 得到（值与分量总是一致）；<code>SqlSugarPersistenceOptions.CommandTimeoutSeconds</code> 改为 <code>TimeSpan CommandTimeout</code>（缺省 <code>StandardCommandTimeout</code>），配置键 <code>CommandTimeoutSeconds</code> 不变</li><li><strong>调整</strong> <code>Caching.Hybrid.HybridCache</code> 改名 <code>HybridObjectCache</code>（与 BCL 的 <code>HybridCache</code> 不再同名），<code>Localization.InMemory.MessageLocalizer</code> 改名 <code>InMemoryMessageLocalizer</code>；Redis 缓存、Redis 消息与 Nacos 选项的用户名统一为 <code>UserName</code>，Kafka 的 <code>GroupId</code> 与 Redis 消息的 <code>GroupName</code> 统一为 <code>ConsumerGroup</code>，配置键改为 <code>XiHan:Messaging:Kafka:ConsumerGroup</code>、<code>XiHan:Messaging:Redis:ConsumerGroup</code>、<code>XiHan:Configuration:Nacos:UserName</code>（值不变，位点照常接续）</li><li><strong>调整</strong> <code>MessageSubscriptions</code> 在消息运行时启动后只读：再 <code>Add</code> 抛 <code>InvalidOperationException</code>，<code>All</code> 与 <code>HandlersFor</code> 交出只读视图；订阅照旧在 <code>Configure</code> 里用 <code>AddMessageHandler</code> 登记</li><li><strong>调整</strong> 缓存键管理的 <code>RemoveByPrefixAsync</code> 返回 <code>Result&lt;long&gt;</code>，空前缀或不合法的前缀返回新错误码 <code>CACHING_VALIDATION_004</code>（HTTP 400）而不是抛 <code>ArgumentException</code>；<code>CacheKeyQuery.Prefix</code> 不合法不再在构造时抛出，由 <code>ListKeysAsync</code> 以同一错误码返回；实现键管理的 Provider 在开头调 <code>CacheKeyQuery.ValidateRemovalPrefix</code></li><li><strong>调整</strong> <code>LockHandle</code> 改为抽象基类：包外实现 <code>IDistributedLock</code> 时派生它并实现 <code>ReleaseCoreAsync</code>，基类保证并发释放也只执行一次；只经 <code>TryAcquireAsync</code> 取句柄的调用方不用改</li><li><strong>调整</strong> AI 护栏的 <code>InspectAsync</code> 改收 <code>GuardrailInspection</code>（<code>Direction</code> 与 <code>Messages</code>），<code>CompleteAsync</code> 拿到响应后再以输出方向检查一次；自写护栏改签名，只看输入的在 <code>Direction</code> 不是 <code>Input</code> 时放行。<code>IKnowledgeStore.SearchAsync</code> 改收 <code>KnowledgeSearch</code>（最低得分由存储施加），<code>TrimAsync</code> 改收 <code>KnowledgeTrim</code> 列表；自写存储按新签名实现</li><li><strong>调整</strong> <code>IJob.RunAsync(run, context)</code> 去掉与 <code>context.CancellationToken</code> 重复的令牌参数，实现里的 <code>cancellationToken</code> 改为 <code>context.CancellationToken</code>；<code>LeaderLease.ReleaseAsync(cancellationToken)</code> 收令牌并返回 <code>Result</code>（幂等，后端没删掉时返回那个失败），实现租约的 Provider 改签名</li><li><strong>调整</strong> <code>JobSchedule.Interval</code> 与 <code>At</code> 改为可空，不适用的计划为 <code>null</code>；<code>JobRunQuery.Trigger</code> 改名 <code>TriggerName</code>（与运行记录同名），新增按触发来源过滤的 <code>Triggers</code>；<code>IHostMonitor</code> 的七个方法改为 <code>Read…Async(cancellationToken)</code>，可能阻塞的读取不占调用方线程、可取消等待；<code>ConfigurationDocument</code> 与 <code>SecretsConfigurationOptions</code> 构造时复制调用方的字典，只差大小写的重复键抛 <code>ArgumentException</code></li><li><strong>调整</strong> <code>UnitOfWorkOptions</code> 改为初始化器：<code>new UnitOfWorkOptions { TenantId = …, IsReadOnly = true, Connection = … }</code>；<code>IUnitOfWork.TenantId</code> / <code>IsReadOnly</code> 改为 <code>unitOfWork.Options.TenantId</code> / <code>Options.IsReadOnly</code>，自己实现工作单元的 Provider 实现 <code>Options</code></li></ul><h3 id="宿主、协议与插件-1" tabindex="-1">宿主、协议与插件 <a class="header-anchor" href="#宿主、协议与插件-1" aria-label="Permalink to “宿主、协议与插件”">​</a></h3><ul><li><strong>调整</strong> AI、协议与宿主的实现类型不再公开：AI 的对话、知识库摄入与检索、提示增强、Provider / 工具 / 提示目录的默认实现，<code>McpServer</code> 的构造与 <code>HandleAsync</code>、<code>McpReply</code>、<code>McpStdioCommand</code>，命令行内置的 <code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code> 命令，<code>HttpRouteConvention.Derive</code> 的布尔重载、<code>OpenApiDocumentBuilder.Build</code> 的五参重载，<code>ProtoMessage</code> 的构造与 <code>S3ObjectStorageFeature.CreateClient</code>；经接口与特性使用的写法不变</li><li><strong>调整</strong> <code>McpTool</code>、<code>McpToolAnnotations</code>（提示缺省为假，只写为真的项）、<code>OutOfProcessPluginStatus</code>、<code>WasmPluginStatus</code>、<code>ParsedCommandLine</code> 改为初始化器；<code>new OpenApiServer(url) { Description = … }</code>、<code>new OpenApiDocumentSource(registry, options) { Permissions = … }</code></li><li><strong>调整</strong> <code>MapXiHanOperations()</code> 返回 <code>IEndpointConventionBuilder</code> 而不是端点数，可以在返回值上给全部操作端点统一加 CORS、限流等约定</li><li><strong>调整</strong> <code>ProblemResponse</code>、<code>HealthResponse</code>、<code>FeatureHealth</code> 改为初始化器，按属性名赋值；响应的 JSON 不变</li><li><strong>修复</strong> <code>Plugins.OutOfProcess</code>、<code>Plugins.Wasm</code>、<code>Plugins.Conformance</code> 对 <code>Plugins.Protocol</code>（以及 Conformance 对两个宿主）改为精确版本依赖：原先单独升级其中一个包，还原能通过，运行时才缺成员；这几个包要用同一版本</li></ul><h3 id="包" tabindex="-1">包 <a class="header-anchor" href="#包" aria-label="Permalink to “包”">​</a></h3><ul><li><strong>优化</strong> NuGet 包换用新图标</li></ul><h2 id="v5-0-0-preview-2-2026-11-06" tabindex="-1">v5.0.0-preview.2（2026-11-06） <a class="header-anchor" href="#v5-0-0-preview-2-2026-11-06" aria-label="Permalink to “v5.0.0-preview.2（2026-11-06）”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，安装要带 <code>--prerelease</code>；公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整</li></ul></div><h3 id="宿主、协议与插件-2" tabindex="-1">宿主、协议与插件 <a class="header-anchor" href="#宿主、协议与插件-2" aria-label="Permalink to “宿主、协议与插件”">​</a></h3><ul><li><strong>修复</strong> <code>invoke</code> 的字段选项按操作的请求 Schema 写成布尔、数字与数组，<code>--times 2</code> 进载荷是 <code>&quot;times&quot;:2</code>；操作没有 Schema 时值仍是字符串（见<a href="/protocols/command-line">命令行</a>）</li></ul><h3 id="包-1" tabindex="-1">包 <a class="header-anchor" href="#包-1" aria-label="Permalink to “包”">​</a></h3><ul><li><strong>优化</strong> 全部包的描述与 README 重写，NuGet 包恢复图标并附更新日志链接</li></ul><h2 id="v5-0-0-preview-1-2026-11-05" tabindex="-1">v5.0.0-preview.1（2026-11-05） <a class="header-anchor" href="#v5-0-0-preview-1-2026-11-05" aria-label="Permalink to “v5.0.0-preview.1（2026-11-05）”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，安装要带 <code>--prerelease</code>；公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整</li></ul></div><h3 id="原语与内核-1" tabindex="-1">原语与内核 <a class="header-anchor" href="#原语与内核-1" aria-label="Permalink to “原语与内核”">​</a></h3><ul><li><strong>新增</strong> 原语层 <code>Primitives</code>：<code>Result</code> / <code>Result&lt;T&gt;</code>、<code>Error</code> 与错误码文法、<code>Maybe&lt;T&gt;</code>、<code>TypedId</code>、<code>InvocationContext</code>、清单模型、<code>PipelineStage</code>、<code>LifecycleState</code>、<code>Stability</code> 与 <code>[ApiLevel]</code>，只增不改</li><li><strong>新增</strong> 内核 <code>Kernel</code>：<code>AddXiHan</code> + <code>UseFeature&lt;T&gt;()</code> 装配特性，按能力 ID 求解能力图谱，<code>XiHan:Providers:&lt;能力 ID&gt;</code> 或 <code>UseProvider</code> 选择 Provider，启动日志打印图谱与管道</li><li><strong>新增</strong> 十一个阶段的执行管道与内置中间件：截止时间、按操作 ID 的熔断 / 限流 / 并发上限（<code>XiHan:Kernel:Resilience</code>）、按 JSON Schema 与 <code>IValidatableObject</code> 的契约校验</li><li><strong>新增</strong> 操作契约与调用器：<code>[Operation]</code>、<code>IOperation&lt;TRequest, TResponse&gt;</code>、<code>OperationRegistry</code>、<code>IOperationInvoker</code>；<code>Kernel.Generators</code> 生成登记代码与请求 / 响应 JSON Schema（<code>XHG001</code>–<code>XHG006</code>），程序集级 <code>OperationDefaults</code> 与只读声明</li><li><strong>新增</strong> 九态生命周期、<code>/health/startup|ready|live</code> 探针、<code>IHealthContributor</code> 与周期探测的 <code>PeriodicHealthContributor</code>，健康条目带说明、检查时刻、耗时与标量数据</li><li><strong>新增</strong> 资源绑定（<code>XiHan:Bindings</code>、<code>SERVICE_BINDING_ROOT</code>）与配置目录 <code>XIHAN_CONFIG_PATH</code> 热更新</li><li><strong>新增</strong> <code>IInvocationAccessor</code> 与调用来源 <code>InvocationOrigin</code>（协议、请求目标、远端地址、User-Agent、端点路由与名字）</li><li><strong>新增</strong> 分析器 <code>Kernel.Analyzers</code>（XH0001–XH0005）与测试基座 <code>Testing</code></li><li><strong>新增</strong> <code>OutboundAddressPolicy.ConnectAsync(host, port, ct)</code>：不是 HTTP 但地址来自用户的连接（SMTP）用同样的规则，返回连好的 <code>Socket</code></li><li><strong>修复</strong> <code>MapXiHanBlobs</code> 的响应带 <code>X-Content-Type-Options: nosniff</code>，写出内容时除 PDF 外带沙箱的 <code>Content-Security-Policy</code>，用户上传的 HTML、SVG 不能在应用的源上运行脚本</li><li><strong>修复</strong> 载荷解码错误的 <code>reason</code> 只写 JSON 路径，不再把请求类型的全名回给调用方</li><li><strong>修复</strong> SqlSugar 的数据库健康项与运行时数据源探测走一次数据库往返并按配置超时：连接池里有空闲连接时不再在库宕了之后报健康，服务器不回话时不再卡住启动；<code>persistence.sqlsugar.database</code> 的错误码由 <code>PERSISTENCE_UNAVAILABLE_003</code> 变成 <code>KERNEL_UNAVAILABLE_005</code>；<code>TestAsync</code> 单次上限是运行时数据源的 <code>HealthProbeIntervalSeconds</code></li><li><strong>修复</strong> 配了从库时授予与租户目录读主库，撤销授予、停用租户的生效时间不再多出复制延迟；新增 <code>UnitOfWorkOptions.ReadsPrimary</code></li><li><strong>调整</strong> HTTP、gRPC、MCP 入站丢弃 Baggage 里的 <code>xihan.tenant</code> 与 <code>xihan.principal</code>，这些调用方的租户只来自认证（CloudEvents 入站不变，端点权限由宿主自己加）；要按主机名或请求头选租户时登记自己的 <code>ITenantResolver</code></li><li><strong>新增</strong> 出站地址策略 <code>OutboundAddressPolicy</code>：工作流 <code>Http</code> 活动、CloudEvents Webhook 与 S3 命名实例缺省只能连公网地址，连接时按实际 IP 判定；连本机或内网要在 <code>XiHan:Security:Outbound</code> 放行，本地开发写 <code>AllowLoopback: true</code>（见<a href="/security/outbound">出站地址策略</a>）</li></ul><h3 id="子系统-1" tabindex="-1">子系统 <a class="header-anchor" href="#子系统-1" aria-label="Permalink to “子系统”">​</a></h3><ul><li><strong>新增</strong> 本地化：消息键与 <code>key.L()</code>、每种语言一个 <code>Localization/&lt;区域&gt;.json</code>、内置 10 种区域（默认 <code>en-US</code>）、宿主按 <code>Accept-Language</code> 翻译 Problem Details；<code>Localization.InMemory</code> 与 <code>Localization.Database</code></li><li><strong>新增</strong> 领域模型 <code>Domain</code>：实体协议接口、值对象、领域事件缓冲与规约</li><li><strong>新增</strong> 持久化：仓储、查询、工作单元与 Transaction 阶段、批量方法、雪花标识生成器；<code>Persistence.InMemory</code>、<code>Persistence.EntityFrameworkCore</code>、<code>Persistence.SqlSugar</code>（多库、分表、差异日志）与 <code>Persistence.Generators</code></li><li><strong>新增</strong> SqlSugar 读写分离：只读工作单元读从库，其余读写走主库；从库权重归一化与周期探测，不可读的自动摘除、全部不可读时读回到主库，健康项 <code>persistence.sqlsugar.replicas</code>（见<a href="/persistence/sqlsugar">持久化</a>）</li><li><strong>新增</strong> 缓存：字节存储、类型化缓存、分布式锁、Idempotency 阶段、<code>IDistributedCache</code> 适配、键管理；<code>Caching.InMemory</code>、<code>Caching.Redis</code>、<code>Caching.Hybrid</code>、<code>Caching.Remote</code>（Experimental）</li><li><strong>新增</strong> 多租户：租户解析与 Tenant 阶段、租户分片与管道外的 <code>TenantShardScope</code>；<code>MultiTenancy.InMemory</code>、<code>MultiTenancy.Database</code></li><li><strong>新增</strong> 安全：认证处理器与 Authenticate 阶段、权限与策略、RBAC 授予、权限收窄过滤器、授予来源、条件引擎、IP 归属地；<code>Security.InMemory</code>、<code>Security.Database</code>、<code>Security.Jwt</code>、<code>Security.OpenIdConnect</code>、<code>Security.Ip2Region</code></li><li><strong>新增</strong> 消息：CloudEvents 信封、发布与订阅（竞争消费与每个实例都收到的广播订阅）、经管道的派发、重试与死信、事务性发件箱、领域事件到消息的登记；<code>Messaging.InMemory</code>、<code>Messaging.RabbitMQ</code>、<code>Messaging.Kafka</code>（流与按时刻重放）</li><li><strong>新增</strong> 对象存储：批量写入与删除、按前缀列举、范围读取、分片上传、预签名、命名存储实例；<code>ObjectStorage.FileSystem</code>、<code>ObjectStorage.S3</code></li><li><strong>新增</strong> 调度：作业与触发器、间隔 / cron / 一次 / 手动计划、日历、misfire、集群分发与失联恢复、领导选举、重试与执行时限；<code>Scheduling.InMemory</code>、<code>Scheduling.Database</code>、<code>Scheduling.Kubernetes</code></li><li><strong>新增</strong> 远程配置与密钥：<code>Configuration.Abstractions</code> 的配置源（轮询重载、失败保留最后一份）与 <code>Configuration.Nacos</code></li><li><strong>新增</strong> 审计：Observe 阶段审计中间件与查询契约；<code>Auditing.InMemory</code>、<code>Auditing.Database</code></li><li><strong>新增</strong> 可观测性：<code>Observability.OpenTelemetry</code> 导出追踪、指标与日志，<code>Observability.Host</code> 读取进程与主机运行信息</li><li><strong>新增</strong> 工作流：JSON 定义模型、定义目录、引擎、内置活动、用户任务、补偿与事件；<code>Workflow.InMemory</code>、<code>Workflow.Database</code></li><li><strong>新增</strong> AI：基于 <code>Microsoft.Extensions.AI</code> 的 Provider 目录、<code>IAIChat</code>、护栏、操作桥接成模型工具、知识库流水线；<code>AI.OpenAI</code>、<code>AI.VectorData</code></li><li><strong>新增</strong> 每个领域的一致性套件 <code>&lt;领域&gt;.Conformance</code>，默认实现与 Provider 通过同一套用例</li></ul><h3 id="宿主、协议与插件-3" tabindex="-1">宿主、协议与插件 <a class="header-anchor" href="#宿主、协议与插件-3" aria-label="Permalink to “宿主、协议与插件”">​</a></h3><ul><li><strong>新增</strong> 宿主 <code>Hosting.AspNetCore</code>（请求桥接、探针、本地化的 Problem Details、绕过管道端点的 <code>XiHan</code> 认证方案）与 <code>Hosting.CommandLine</code>（<code>help</code> / <code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code>，按错误 KIND 的退出码）</li><li><strong>新增</strong> 协议适配器 <code>Protocols.Http</code>（路由推导、OpenAPI 3.1 与权限扩展）、<code>Protocols.Grpc</code>（由 Schema 推出 protobuf、<code>/operations.proto</code>）、<code>Protocols.Mcp</code>（Streamable HTTP 与 stdio）、<code>Protocols.CloudEvents</code>（入站 <code>/events</code> 与出站 Webhook）</li><li><strong>新增</strong> 插件协议 <code>xihan.plugin.v1</code> 与三种宿主：<code>Plugins.InProcess</code>、<code>Plugins.OutOfProcess</code>、<code>Plugins.Wasm</code>（Experimental），黑盒套件 <code>Plugins.Conformance</code></li><li><strong>新增</strong> 组合包 <code>Profiles.Minimal</code>、<code>Profiles.Standard</code>、<code>Profiles.Full</code></li><li><strong>新增</strong> 命令行工具 <code>xihan</code>：<code>pack</code> 从 <code>xihan.app.json</code> 生成 Dockerfile、Kustomize、Compose 与 Aspire 产物，<code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code> 转发给应用</li></ul>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};